import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
export function localEnvironment(c){
 for(const key of ['phone_controller','adb_host_config','phone_registry']){
  const p=c[key];if(typeof p!=='string'||!path.isAbsolute(p)||fs.lstatSync(p).isSymbolicLink()||!fs.statSync(p).isFile()||crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')!==c[key+'_sha256'])throw Error('TRANSPORT_SOURCE_CHANGED');
 }
 if(!fs.realpathSync(c.phone_controller).startsWith(fs.realpathSync(c.runtime_root)+path.sep))throw Error('CONTROLLER_SOURCE_SCOPE');
 return {...process.env,ZJ_ADB_HOST_CONFIG:c.adb_host_config,DOUYIN_PHONE_REGISTRY:c.phone_registry};
}

